export const DEFAULT_SELECTED = ['iphone', 'ipad-mini', 'laptop'] as const

const DEMO_MAX_HEIGHT = 360

/** Same fit scaling as `viewportScale` in the extension. */
export function viewportScale(
  zoom: ZoomMode,
  size: { width: number; height: number },
  box: { width: number | null; maxHeight: number },
): number {
  if (zoom !== 'fit') return Number(zoom)
  const byHeight = box.maxHeight / size.height
  const byWidth = box.width == null ? Infinity : box.width / size.width
  return Math.max(0.05, Math.min(1, byWidth, byHeight))
}

function frameHeight(device: { width: number; height: number }) {
  const scale = viewportScale('fit', device, { width: null, maxHeight: DEMO_MAX_HEIGHT })
  return Math.round(device.height * scale)
}

export const ALL_DEVICES: Device[] = PRESETS.map((device) => ({
  ...device,
  frame: frameHeight(device),
}))

