const BREAKPOINTS = [
  ['2xl', 1536],
  ['xl', 1280],
  ['lg', 1024],
  ['md', 768],
  ['sm', 640],
] as const

export function breakpointFor(width: number): string {
  return BREAKPOINTS.find(([, min]) => width >= min)?.[0] ?? 'xs'
}

